import sys
import json

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    idx = 0
    n = int(data[idx].strip())
    idx += 1

    points = []
    for _ in range(n):
        x, y = map(int, data[idx].strip().split())
        points.append({"x": x, "y": y})
        idx += 1

    m = int(data[idx].strip())
    idx += 1

    triangles = []
    for _ in range(m):
        i, j, k = map(int, data[idx].strip().split())
        triangles.append([i, j, k])
        idx += 1

    output = {
        "n": n,
        "points": points,
        "m": m,
        "triangles": triangles
    }

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

